import React, { createContext, useState, useContext, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useModal } from './ModalContext';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);

  const navigate = useNavigate();
  const { showModal } = useModal();

  // Загружаем данные из localStorage при старте
  useEffect(() => {
    const loadUserData = async () => {
      try {
        setLoading(true);

        // Проверяем localStorage
        const savedUser = localStorage.getItem('luxury_user');
        const savedToken = localStorage.getItem('luxury_token');
        const savedCart = localStorage.getItem('luxury_cart');
        const savedFavorites = localStorage.getItem('luxury_favorites');
        const savedOrders = localStorage.getItem('luxury_orders');

        if (savedUser && savedToken) {
          // Проверяем валидность токена (можно добавить проверку срока)
          const tokenExpiry = JSON.parse(atob(savedToken.split('.')[1])).exp;
          const currentTime = Math.floor(Date.now() / 1000);

          if (tokenExpiry > currentTime) {
            setUser(JSON.parse(savedUser));
            setToken(savedToken);
          } else {
            // Токен истёк, очищаем localStorage
            clearLocalStorage();
          }
        }

        // Загружаем корзину, избранное и заказы
        if (savedCart) setCart(JSON.parse(savedCart));
        if (savedFavorites) setFavorites(JSON.parse(savedFavorites));
        if (savedOrders) setOrders(JSON.parse(savedOrders));

      } catch (error) {
        console.error('Error loading user data:', error);
        clearLocalStorage();
      } finally {
        setLoading(false);
      }
    };

    loadUserData();
  }, []);

  // Сохраняем данные в localStorage при изменениях
  useEffect(() => {
    if (user) {
      localStorage.setItem('luxury_user', JSON.stringify(user));
    }
  }, [user]);

  useEffect(() => {
    if (token) {
      localStorage.setItem('luxury_token', token);
    }
  }, [token]);

  useEffect(() => {
    localStorage.setItem('luxury_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('luxury_favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    localStorage.setItem('luxury_orders', JSON.stringify(orders));
  }, [orders]);

  // Регистрация пользователя
  const register = async (username, email, password) => {
    try {
      setLoading(true);

      // Проверяем, существует ли пользователь
      const existingUsers = JSON.parse(localStorage.getItem('luxury_users') || '[]');
      const existingUser = existingUsers.find(u => u.email === email);

      if (existingUser) {
        throw new Error('Пользователь с таким email уже существует');
      }

      // Создаём нового пользователя
      const newUser = {
        id: Date.now().toString(),
        username,
        email,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      // Сохраняем пользователя в "базу данных" (localStorage)
      const updatedUsers = [...existingUsers, { ...newUser, password }];
      localStorage.setItem('luxury_users', JSON.stringify(updatedUsers));

      // Создаём JWT токен (упрощённый вариант)
      const newToken = generateToken(newUser.id);

      // Устанавливаем состояние
      setUser(newUser);
      setToken(newToken);

      // Показываем уведомление
      showModal('success', null, 'Регистрация успешна!', 'Добро пожаловать в Luxury Brands!');

      return { success: true, user: newUser };

    } catch (error) {
      console.error('Registration error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // Вход пользователя
  const login = async (email, password) => {
    try {
      setLoading(true);

      // Ищем пользователя в "базе данных"
      const existingUsers = JSON.parse(localStorage.getItem('luxury_users') || '[]');
      const userData = existingUsers.find(u => u.email === email);

      if (!userData) {
        throw new Error('Пользователь не найден');
      }

      // Проверяем пароль (в реальном приложении должно быть хеширование)
      if (userData.password !== password) {
        throw new Error('Неверный пароль');
      }

      // Убираем пароль из данных пользователя
      const { password: _, ...safeUserData } = userData;

      // Создаём токен
      const newToken = generateToken(safeUserData.id);

      // Устанавливаем состояние
      setUser(safeUserData);
      setToken(newToken);

      return { success: true, user: safeUserData };

    } catch (error) {
      console.error('Login error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // Выход
  const logout = () => {
    // Очищаем состояние
    setUser(null);
    setToken(null);

    // Очищаем localStorage (кроме пользователей)
    localStorage.removeItem('luxury_user');
    localStorage.removeItem('luxury_token');

    // Перенаправляем на главную
    navigate('/');
  };

  // Функции для корзины
  const addToCart = (product) => {
    setCart(prevCart => {
      const existingItem = prevCart.find(item => item.id === product.id);

      if (existingItem) {
        // Если товар уже в корзине, увеличиваем количество
        return prevCart.map(item =>
          item.id === product.id
            ? { ...item, quantity: (item.quantity || 1) + 1 }
            : item
        );
      } else {
        // Добавляем новый товар
        return [...prevCart, { ...product, quantity: 1 }];
      }
    });

    showModal('success', null, 'Товар добавлен в корзину');
  };

  const removeFromCart = (productId) => {
    setCart(prevCart => prevCart.filter(item => item.id !== productId));
  };

  const updateCartQuantity = (productId, quantity) => {
    if (quantity < 1) {
      removeFromCart(productId);
      return;
    }

    setCart(prevCart =>
      prevCart.map(item =>
        item.id === productId ? { ...item, quantity } : item
      )
    );
  };

  const clearCart = () => {
    setCart([]);
  };

  // Функции для избранного
  const addToFavorites = (product) => {
    setFavorites(prevFavorites => {
      if (prevFavorites.find(item => item.id === product.id)) {
        return prevFavorites;
      }
      return [...prevFavorites, product];
    });

    showModal('success', null, 'Товар добавлен в избранное');
  };

  const removeFromFavorites = (productId) => {
    setFavorites(prevFavorites =>
      prevFavorites.filter(item => item.id !== productId)
    );
  };

  // Функции для заказов
  const createOrder = (orderData) => {
    const newOrder = {
      id: `ORDER-${Date.now()}`,
      userId: user?.id,
      items: [...cart],
      total: cart.reduce((sum, item) => sum + (item.price || 0) * (item.quantity || 1), 0),
      date: new Date().toISOString(),
      status: 'pending',
      address: orderData.address,
      cardNumber: orderData.cardNumber ? `**** **** **** ${orderData.cardNumber.slice(-4)}` : 'Оплата при получении',
      contactEmail: user?.email,
    };

    setOrders(prevOrders => [newOrder, ...prevOrders]);
    clearCart(); // Очищаем корзину после оформления заказа

    return newOrder;
  };

  const cancelOrder = (orderId) => {
    setOrders(prevOrders =>
      prevOrders.map(order =>
        order.id === orderId ? { ...order, status: 'cancelled' } : order
      )
    );
  };

  // Вспомогательные функции
  const generateToken = (userId) => {
    // Упрощённый JWT токен (в реальном приложении используйте библиотеку)
    const header = { alg: 'HS256', typ: 'JWT' };
    const payload = {
      userId,
      exp: Math.floor(Date.now() / 1000) + (7 * 24 * 60 * 60), // 7 дней
    };

    const encodedHeader = btoa(JSON.stringify(header));
    const encodedPayload = btoa(JSON.stringify(payload));
    const signature = btoa('luxury-secret-key'); // В реальном приложении используйте безопасный ключ

    return `${encodedHeader}.${encodedPayload}.${signature}`;
  };

  const clearLocalStorage = () => {
    localStorage.removeItem('luxury_user');
    localStorage.removeItem('luxury_token');
    localStorage.removeItem('luxury_cart');
    localStorage.removeItem('luxury_favorites');
    localStorage.removeItem('luxury_orders');
  };

  // Проверяем, авторизован ли пользователь
  const isAuthenticated = !!user && !!token;

  const value = {
    // Основные данные
    user,
    token,
    loading,
    isAuthenticated,

    // Аутентификация
    register,
    login,
    logout,

    // Корзина
    cart,
    addToCart,
    removeFromCart,
    updateCartQuantity,
    clearCart,

    // Избранное
    favorites,
    addToFavorites,
    removeFromFavorites,

    // Заказы
    orders,
    createOrder,
    cancelOrder,

    // Вспомогательные
    updateUser: (updatedData) => {
      setUser(prev => ({ ...prev, ...updatedData }));
    },
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
